"""Original oncologic emergencies: tumor lysis and initial hypercalcemia care."""
from create_oncology_neutropenic_emergencies import rows,q,FN,NS,ref
TL=ref('eviQ tumor lysis prevention and management principles','https://www.eviq.org.au/clinical-resources/side-effect-and-toxicity-management/prophylaxis-and-treatment/108-prevention-of-tumour-lysis-syndrome')
RA=ref('Rasburicase prescribing information','https://products.sanofi.us/elitek/elitek.html')
HC=ref('Endocrine Society hypercalcemia of malignancy guideline','https://www.endocrine.org/clinical-practice-guidelines/hypercalcemia')

q('After treatment of a bulky highly proliferative tumor, a patient develops AKI, high potassium, high phosphate, high urate and low calcium. Which syndrome best fits?', 'Tumor lysis syndrome',[
 ('Isolated hypoparathyroidism','This does not explain the combined urate, potassium and renal pattern.'),('Primary hyperaldosteronism','This usually drives potassium in the opposite direction.'),('Hypercalcemia of malignancy','The calcium direction and lysis pattern differ.')],
 'Rapid cell breakdown releases an intracellular solute load','**Potassium, phosphate and nucleic-acid metabolism create acute systemic hazards.**',['Phosphate can lower calcium and promote calcium-phosphate deposition.','Urate and other factors contribute to kidney injury.'],'**Monitor rhythm and treat urgent abnormalities while supporting renal function.**',['Use risk-based hydration and urate treatment.','Dialysis may be needed for refractory complications.'],[['Released load','Potassium/phosphate/nucleic acids'],['Calcium','Can fall'],['Organs','Kidney and cardiac danger']],[TL],style='clinical_scenario')

q('Which baseline profile most strongly increases tumor-lysis risk?', 'Bulky highly treatment-sensitive proliferative disease with high LDH and impaired kidney function',[
 ('Small indolent disease with normal kidney function as the highest-risk pattern','That generally has a lower risk profile.'),('Any cancer regardless of burden or therapy has identical risk','Risk varies substantially.'),('A normal serum calcium guarantees no future lysis','Calcium before treatment does not remove the risk.')],
 'Risk combines tumor biology, burden and host clearance','**Rapid potential cell kill is especially important.**',['Novel targeted therapies can produce TLS even outside classic cytotoxic regimens.','Baseline renal impairment reduces tolerance of the solute load.'],'**Stratify before treatment and arrange prophylaxis/monitoring.**',['Review hydration feasibility and serial laboratory access.','Reassess when therapy or disease burden changes.'],[['Tumor','Burden/proliferation/sensitivity'],['Host','Kidney clearance'],['Plan','Risk-adapted prevention']],[TL])

q('How does rasburicase differ from allopurinol in urate management?', 'Rasburicase degrades existing uric acid, while allopurinol reduces new uric-acid formation',[
 ('Both rapidly remove existing urate by the same enzyme reaction','Their mechanisms differ.'),('Allopurinol directly converts uric acid to allantoin','That is rasburicase’s urate-oxidase action.'),('Rasburicase blocks xanthine oxidase','That is allopurinol’s relevant target.')],
 'Prevention of production differs from removal of the existing load','**Urate oxidase converts uric acid to a more soluble product.**',['Xanthine-oxidase inhibition can increase upstream purine metabolites.','Choice depends on risk, existing urate and contraindications.'],'**Use the appropriate protocol rather than treating the agents as interchangeable.**',['Monitor urate, electrolytes and renal function.','Avoid unnecessary overlapping strategies without a specific rationale.'],[['Rasburicase','Existing urate degradation'],['Allopurinol','Reduced new formation'],['Selection','Risk and safety']],[TL,RA])

q('Why is G6PD deficiency a major contraindication to rasburicase?', 'Oxidative products of urate degradation can provoke hemolysis and methemoglobinemia',[
 ('Rasburicase causes vitamin K deficiency as its defining toxicity','This is not the relevant mechanism.'),('G6PD deficiency makes uric acid entirely absent','It does not.'),('The contraindication is only a theoretical lack of efficacy without safety risk','Severe oxidative toxicity can occur.')],
 'A useful enzyme reaction can create a host-specific oxidant hazard','**Hydrogen peroxide generation is relevant to the risk.**',['Screen according to the recommended protocol before use.','Do not interpret high TLS risk as removing this contraindication.'],'**Use an alternative specialist plan when contraindicated.**',['Monitor for hemolysis and abnormal oxygenation if exposure has occurred.','Arrange urgent treatment of severe complications.'],[['Host factor','G6PD deficiency'],['Hazard','Oxidative injury'],['Effects','Hemolysis/methemoglobinemia']],[RA,TL])

q('A patient on rasburicase has an unexpectedly extremely low uric-acid result from a sample left at room temperature. Which preanalytical problem is possible?', 'Continued ex vivo urate degradation can artifactually lower the measured result',[
 ('Rasburicase necessarily raises measured urate in the tube','Its enzyme action lowers urate.'),('The result proves all tumor-lysis risk has ended','A sample artifact and ongoing electrolyte hazards remain possible.'),('Urate sampling conditions never affect results during treatment','Special handling is required.')],
 'The drug can continue acting after the blood leaves the patient','**Use the product’s specified chilled collection and rapid processing procedure.**',['Incorrect handling can produce a falsely reassuring result.','Electrolyte and renal trends remain essential regardless of urate.'],'**Repeat with appropriate laboratory handling if needed.**',['Coordinate with the laboratory before sampling.','Do not reduce monitoring from one implausible result.'],[['Issue','Ex vivo enzyme activity'],['Bias','Falsely low urate'],['Prevention','Specified chilled rapid handling']],[RA],style='clinical_scenario')

q('Why is routine urine alkalinization generally avoided in TLS prevention when modern urate therapy is available?', 'It can promote calcium-phosphate precipitation, especially when phosphate rises',[
 ('Alkaline urine always removes every TLS metabolite safely','Different solutes have different precipitation behavior.'),('Alkalinization reliably prevents hyperkalemia','It does not remove the potassium load.'),('The aim is to force systemic severe acidemia','Avoiding routine alkalinization does not mean inducing acidosis.')],
 'Improving one solute’s chemistry can worsen another’s','**TLS is more than a uric-acid problem.**',['Hydration and risk-appropriate urate management are central.','Treat systemic acid-base emergencies on their own indications.'],'**Monitor phosphate, calcium, potassium and kidney function.**',['Avoid routine bicarbonate solely to alkalinize urine.','Use nephrology input for refractory metabolic complications.'],[['Alkalinization','Calcium-phosphate risk'],['Urate','Specific pharmacological management'],['Monitoring','Multiple solutes']],[TL])

q('TLS causes low calcium but the patient has no tetany, seizure or arrhythmia. Which principle is appropriate?', 'Avoid reflexive calcium replacement solely to normalize the number; manage phosphate and assess symptoms',[
 ('Give large calcium doses routinely regardless of phosphate','This can increase calcium-phosphate deposition risk.'),('Never give calcium even for a life-threatening symptomatic complication','Severe symptoms can require cautious treatment.'),('Low calcium proves the high phosphate is harmless','The combination is part of the danger.')],
 'Treat the clinical and precipitation risk together','**Asymptomatic hypocalcemia in TLS is not managed like every other calcium deficit.**',['Symptomatic severe hypocalcemia is a different urgent situation.','Phosphate burden and kidney function guide definitive correction.'],'**Use close ECG and biochemical monitoring.**',['Consider dialysis for refractory severe electrolyte/renal complications.','Avoid worsening the calcium-phosphate load.'],[['Asymptomatic low calcium','No automatic replacement'],['Severe symptoms','Cautious indicated treatment'],['Underlying issue','Phosphate and renal handling']],[TL],style='clinical_scenario')

q('A patient with malignancy has calcium 16 mg/dL, dehydration and confusion. Which initial treatment combination is most appropriate?', 'Tailored isotonic fluids, an antiresorptive agent and short-course calcitonin for rapid bridging when indicated',[
 ('Calcitonin alone as durable therapy for weeks','Tachyphylaxis limits its sustained role.'),('Routine loop diuretic before restoring circulating volume','This can worsen dehydration.'),('Wait for complete tumor staging before treating calcium','Severe symptomatic hypercalcemia is an immediate medical problem.')],
 'Bridge immediate physiological control to sustained calcium reduction','**Hydration and antiresorptive treatment address different components.**',['Calcitonin can act rapidly while the longer-acting agent takes effect.','Kidney/cardiac function constrains fluid and drug choices.'],'**Monitor response and treat the cancer mechanism.**',['Avoid fixed large-volume regimens in every patient.','Assess phosphate, magnesium and later hypocalcemia.'],[['Fluids','Correct depletion'],['Calcitonin','Rapid short bridge'],['Antiresorptive','Sustained effect']],[HC],style='clinical_scenario')
